const direction=document.querySelector('#direction');const tips={'Термочехлы':'Укажите оборудование, температуру, условия эксплуатации и размеры.','Чехлы для транспорта':'Укажите модель сиденья, материал и количество чехлов.','Чехлы и обивка для мебели':'Укажите модель мебели, состав деталей, материал и объём заказа.'};function update(){document.querySelector('#tip').textContent=tips[direction.value]}direction.addEventListener('change',update);update();document.querySelectorAll('.choose').forEach(a=>a.addEventListener('click',()=>{direction.value=a.dataset.direction;update()}));document.querySelector('#brief').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;const body='Здравствуйте!\n\nНаправление: '+direction.value+'\nЗадача: '+form.description.value+'\nЖелаемый срок: '+form.deadline.value+'\nКонтакт для связи: '+form.reply.value+'\n\nФотографии и чертежи приложу к письму.';window.location.href='mailto:mingaray26@yandex.ru?subject='+encodeURIComponent('Запрос: '+direction.value)+'&body='+encodeURIComponent(body);document.querySelector('#form-status').textContent='Письмо подготовлено для почтовой программы. Если она не открылась, напишите на mingaray26@yandex.ru. Данные с этой страницы не отправлены.'});
